   174|/** POST a new owner-approved job to the worker queue. */
   175|export async function handleSeniorDeveloperWorkerEnqueueRequest(request: Request): Promise<Response> {
   176|  try {
   177|    const signedWorkerRequest = request.headers.has('X-IVX-Deploy-Signature');
   178|    const internalAuthorization = signedWorkerRequest ? await authorizeInternalDeploymentRequest(request) : null;
   179|    const ownerAuthorization = internalAuthorization ? null : await assertIVXRegisteredOwnerBearer(request, 'senior_developer_worker_enqueue');
   180|    const approval = ownerAuthorization?.approval ?? {
   181|      ownerSessionDetected: true,
   182|      bearerAccepted: true,
   183|      ownerVerified: true,
   184|      ownerEmailMatched: true,
   185|      ownerEmailMasked: 'internal-worker',
   186|      userId: `worker:${internalAuthorization?.workerId ?? 'unknown'}`,
   187|      role: 'internal_worker',
   188|      guardMode: 'strict' as const,
   189|      allowlistConfigured: true,
   190|      action: 'senior_developer_worker_enqueue',
   191|      blocker: null,
   192|      secretValuesReturned: false as const,
   193|    };
   194|    const body = await request.json().catch((): WorkerEnqueueRequest => ({}));
   195|    const goal = readTrimmed(body.goal);
   196|    const templateMode = normalizeTemplateMode(body.templateMode);
   197|    const isSystemMode = (approval.role === 'system' && approval.guardMode === 'system_bypass') || internalAuthorization !== null;
   198|    const proposedPlan = readTrimmed(body.proposedPlan);
   199|    const filesAffected = readStringArray(body.filesAffected);
   200|    const riskLevel = normalizeRiskLevel(body.riskLevel);
   201|    const rollbackOption = readTrimmed(body.rollbackOption);
   202|    const approveGitDeploy = readBoolean(body.approveGitDeploy);
   203|    const approvePatch = readBoolean(body.approvePatch);
   204|    const executionMode = resolveWorkerExecutionMode(body.executionMode, approvePatch, approveGitDeploy);
   205|
   206|    if (!goal) {
   207|      return ownerOnlyJson({
   208|        ok: false,
   209|        marker: IVX_SENIOR_DEV_WORKER_MARKER,
   210|        error: 'A senior developer goal is required.',
   211|        ownerApproval: approval,
   212|        secretValuesReturned: false,
   213|        timestamp: new Date().toISOString(),
   214|      }, 400);
   215|    }
   216|
   217|    if (!isSystemMode && approveGitDeploy && (!proposedPlan || filesAffected.length === 0 || !rollbackOption)) {
   218|      return ownerOnlyJson({
   219|        ok: false,
   220|        marker: IVX_SENIOR_DEV_WORKER_MARKER,
   221|        error: 'Owner-approved production mutation requires a visible proposed plan, files affected, risk level, and rollback option before commit/deploy.',
   222|        exactBlocker: 'approval_contract_missing_plan_files_or_rollback',
   223|        requiredFields: ['proposedPlan', 'filesAffected', 'riskLevel', 'rollbackOption'],
   224|        ownerApproval: approval,
   225|        secretValuesReturned: false,
   226|        timestamp: new Date().toISOString(),
   227|      }, 400);
   228|    }
   229|
   230|    const ownerApprovedAction = {
   231|      proposedPlan,
   232|      filesAffected,
   233|      riskLevel,
   234|      rollbackOption,
   235|      rollbackAvailable: rollbackOption.length > 0,
   236|      auditLog: [
   237|        `templateMode=${templateMode}`,
   238|        `ownerSessionDetected=${approval.ownerSessionDetected}`,
   239|        `bearerAccepted=${approval.bearerAccepted}`,
   240|        `ownerVerified=${approval.ownerVerified}`,
   241|        `role=${approval.role}`,
   242|        `guardMode=${approval.guardMode}`,
   243|        `filesAffected=${filesAffected.join(', ')}`,
   244|        `riskLevel=${riskLevel}`,
   245|        ...(internalAuthorization ? [`internalWorkerId=${internalAuthorization.workerId}`, `ownerApprovalId=${internalAuthorization.approvalId}`, `requestedCommitSha=${internalAuthorization.requestedCommitSha}`] : []),
   246|      ],
   247|      secretValuesReturned: false as const,
   248|    };
   249|
   250|    // Prefix the execution template so the worker scaffolds the right shape of
   251|    // work (whole app, module, feature, fix, refactor, or a business workflow).
   252|    const ownerId = internalAuthorization ? `worker:${internalAuthorization.workerId}` : (approval.ownerSessionDetected ? (approval as Record<string, unknown>).userId as string ?? 'owner' : 'owner');
   253|    const input: IVXWorkerJobInput = {
   254|      goal: `[TEMPLATE_MODE:${templateMode}] ${goal}`,
   255|      ownerApproved: true,
   256|      approvePatch,
   257|      approveGitDeploy,
   258|      // The owner-gated route has already verified the approval contract above.
   259|      // Persist the canonical confirmation so the autonomous deploy runner receives
   260|      // the same authorization that selected executionMode='deploy'.
   261|      gitDeployConfirmationText: approveGitDeploy ? 'CONFIRM_IVX_RENDER_DEPLOY' : '',
   262|      executionMode,
   263|      validationMode: normalizeValidationMode(body.validationMode),
   264|      systemMode: isSystemMode,
   265|      ownerApprovedAction,
   266|      ownerId,
   267|    };
   268|
   269|    const { job, attached, activeJobId } = await enqueueOrAttachSeniorDeveloperJob(input);
   270|    const statusCode = attached ? 409 : 202;
   271|    return ownerOnlyJson({
   272|      ok: attached ? false : true,
   273|      ownerOnly: true,
   274|      ownerApproval: approval,
   275|      marker: IVX_SENIOR_DEV_WORKER_MARKER,
   276|      job,
   277|      jobId: job.jobId,
   278|      attached,
   279|      activeJobId: activeJobId ?? (attached ? job.jobId : null),
   280|      templateMode,
   281|      executionMode,
   282|      poll: `GET /api/ivx/senior-developer/worker/jobs/${job.jobId}`,
   283|      message: attached
   284|        ? `A job is already running for this owner. Your request was attached to the active job (${job.jobId}). Poll its status instead of creating a duplicate.`
   285|        : 'Job enqueued. Poll the job endpoint for status updates.',
   286|      secretValuesReturned: false,
   287|      timestamp: new Date().toISOString(),
   288|    }, statusCode);
   289|  } catch (error) {
   290|    return errorResponse(error);
   291|  }
