   459|    const data = await res.json() as { content?: string };
   460|    if (!data.content) return null;
   461|    const decoded = Buffer.from(data.content, 'base64').toString('utf8');
   462|    const doc = JSON.parse(decoded) as LedgerDoc;
   463|    if (!Array.isArray(doc.entries)) return null;
   464|    return { ...doc, marker: IVX_SENIOR_DEV_WORKER_MARKER, durable: true };
   465|  } catch {
