   470|async function githubEnsureLedgerBranch(): Promise<boolean> {
   471|  const repo = ledgerGithubRepo();
   472|  try {
   473|    const refRes = await fetch(
   474|      `https://api.github.com/repos/${repo}/git/ref/heads/${LEDGER_GITHUB_BRANCH}`,
   475|      { headers: ledgerGithubHeaders(), signal: AbortSignal.timeout(10000) },
   476|    );
   477|    if (refRes.ok) return true;
   478|    const mainRes = await fetch(
   479|      `https://api.github.com/repos/${repo}/git/ref/heads/main`,
   480|      { headers: ledgerGithubHeaders(), signal: AbortSignal.timeout(10000) },
   481|    );
   482|    if (!mainRes.ok) return false;
   483|    const mainData = await mainRes.json() as { object?: { sha?: string } };
   484|    const baseSha = mainData.object?.sha;
   485|    if (!baseSha) return false;
   486|    const createRes = await fetch(`https://api.github.com/repos/${repo}/git/refs`, {
   487|      method: 'POST',
   488|      headers: ledgerGithubHeaders(),
   489|      body: JSON.stringify({ ref: `refs/heads/${LEDGER_GITHUB_BRANCH}`, sha: baseSha }),
   490|      signal: AbortSignal.timeout(10000),
   491|    });
   492|    return createRes.ok;
   493|  } catch {
   494|    return false;
   495|  }
