   498|async function githubLedgerWrite(doc: LedgerDoc): Promise<boolean> {
   499|  const token = ledgerGithubToken();
   500|  if (!token) return false;
   501|  const repo = ledgerGithubRepo();
   502|  try {
   503|    if (!(await githubEnsureLedgerBranch())) return false;
   504|    let existingSha: string | undefined;
   505|    const currentRes = await fetch(
   506|      `https://api.github.com/repos/${repo}/contents/${LEDGER_FILE}?ref=${LEDGER_GITHUB_BRANCH}`,
   507|      { headers: ledgerGithubHeaders(), signal: AbortSignal.timeout(10000) },
   508|    );
   509|    if (currentRes.ok) {
   510|      const current = await currentRes.json() as { sha?: string };
   511|      existingSha = current.sha;
   512|    }
   513|    const putRes = await fetch(
   514|      `https://api.github.com/repos/${repo}/contents/${LEDGER_FILE}`,
   515|      {
   516|        method: 'PUT',
   517|        headers: ledgerGithubHeaders(),
   518|        body: JSON.stringify({
   519|          message: `chore(ledger): proof ledger update ${nowIso()}`,
   520|          content: Buffer.from(JSON.stringify(doc, null, 2), 'utf8').toString('base64'),
   521|          branch: LEDGER_GITHUB_BRANCH,
   522|          ...(existingSha ? { sha: existingSha } : {}),
   523|        }),
   524|        signal: AbortSignal.timeout(15000),
   525|      },
   526|    );
   527|    return putRes.ok;
   528|  } catch {
   529|    return false;
   530|  }
