   533|async function appendLedger(result: IVXWorkerJobResult): Promise<void> {
   534|  // Phase 12: fingerprint the evidence and reject duplicate redeploys as
   535|  // separate completed development tasks. A duplicate fingerprint (same
   536|  // commitSha + deployId + filesChanged + finalStatus) is logged but the entry
   537|  // is still recorded (marked as duplicate) so the ledger is complete.
   538|  const fingerprint = fingerprintEvidence({
   539|    commitSha: result.commitSha,
   540|    deployId: result.deployId,
   541|    filesChanged: result.changedFiles,
   542|    finalStatus: result.finalStatus,
   543|  });
   544|  result.evidenceFingerprint = fingerprint;
   545|  const current = await loadLedger();
   546|  const priorMatch = current.entries.find((e) => e.evidenceFingerprint === fingerprint && e.jobId !== result.jobId);
   547|  if (priorMatch) {
   548|    appendDurableEvent(LEDGER_FILE, { type: 'duplicate_evidence_rejected', jobId: result.jobId, priorJobId: priorMatch.jobId, fingerprint }).catch(() => {});
   549|  }
   550|  const entries = [result, ...current.entries.filter((e) => e.jobId !== result.jobId)].slice(0, MAX_LEDGER_RETAINED);
   551|  const doc: LedgerDoc = {
   552|    marker: IVX_SENIOR_DEV_WORKER_MARKER,
   553|    durable: isDurableStoreConfigured(),
   554|    updatedAt: nowIso(),
   555|    entries,
   556|  };
   557|  memoryLedger = doc;
   558|  if (isDurableStoreConfigured()) {
   559|    try {
   560|      await writeDurableJson(LEDGER_FILE, doc);
   561|      await appendDurableEvent(LEDGER_FILE, { type: 'proof_ledger_entry', ...result } as Record<string, unknown>);
   562|    } catch {
   563|      // Durable write failed — in-memory ledger still holds the entry.
   564|    }
   565|  } else {
   566|    // No Supabase service key in this runtime — persist to the GitHub side
   567|    // branch so proof survives Render's diskless deploy restarts.
   568|    await githubLedgerWrite({ ...doc, durable: true });
   569|  }
